import type { CardCheck } from '@/lib/flashcard-check-core'

/**
 * Card-check questions for the cards of `mcat-molecular-biology-translation-mcat`: one per card, keyed by the
 * card's exact front text. Each asks the student to use the card's idea in a
 * new situation. Gate: scripts/flashcard-checks/validate.ts.
 */
const r = String.raw

export const checks: Record<string, CardCheck> = {
  [r`What are the three ribosomal binding sites?`]: {
    question: r`A tRNA delivers the fifth amino acid of a growing protein and later leaves the ribosome. In what order does this tRNA pass through the ribosomal sites?`,
    options: [r`P site, then A site, then E site`, r`E site, then P site, then A site`, r`A site, then P site, then E site`, r`A site, then E site, then P site`],
    correctAnswer: 2,
    explanation: r`An elongator tRNA arrives at the A (aminoacyl) site, holds the chain in the P (peptidyl) site after translocation, and leaves from the E (exit) site. Starting at P describes only the initiator tRNA, and the orders that start at E or put E before P reverse what "exit" means.`,
  },
  [r`What is a signal sequence?`]: {
    question: r`A researcher deletes the hydrophobic stretch of about 20 residues at the N-terminus of a normally secreted hormone. The altered protein will most likely:`,
    options: [r`be completed and stay in the cytosol`, r`be secreted without any sugar chains`, r`enter the ER and remain in its lumen`, r`be imported into the nucleus instead`],
    correctAnswer: 0,
    explanation: r`The N-terminal signal sequence is what sends the ribosome to the rough ER, so without it the protein is finished on a free ribosome and stays in the cytosol. Secretion and ER retention both require entering the ER first, and nuclear import needs its own, different signal.`,
  },
  [r`What is the start codon and what does it encode?`]: {
    question: r`A bacterial mRNA and a human cytosolic mRNA each begin their coding region with AUG. Which residue starts the polypeptide in each case?`,
    options: [r`Methionine in the bacterium, formyl-methionine in the human cell`, r`Formyl-methionine in both the bacterium and the human cell`, r`Plain methionine in both the bacterium and the human cell`, r`Formyl-methionine in the bacterium, methionine in the human cell`],
    correctAnswer: 3,
    explanation: r`AUG codes for methionine, and only prokaryotes start with the formylated form. The swapped option gives the formyl group to the wrong organism, and the two "both" options ignore that the bacterial and eukaryotic initiator residues differ.`,
  },
  [r`Name the three stop codons.`]: {
    question: r`A ribosome starts at the AUG of this message and reads in frame: 5'-AUG GCU UGG UGA CUU UAA-3'. How many amino acids does the released peptide contain?`,
    options: [r`2 amino acids`, r`3 amino acids`, r`4 amino acids`, r`5 amino acids`],
    correctAnswer: 1,
    explanation: r`UGA is a stop codon, so translation ends after AUG, GCU and UGG, giving 3 residues. Counting 4 treats UGA as a sense codon, counting 5 reads on to UAA as if it were the first stop, and 2 wrongly treats UGG (tryptophan) as a stop.`,
  },
  [r`What are common post-translational modifications?`]: {
    question: r`Which of the following changes is NOT a post-translational modification of a protein?`,
    options: [r`Adding a phosphate to a serine residue`, r`Splicing an intron out of its transcript`, r`Forming a disulfide between cysteines`, r`Cleaving a zymogen to its active form`],
    correctAnswer: 1,
    explanation: r`Splicing acts on the pre-mRNA before translation, so it is RNA processing, not a change to the finished polypeptide. Phosphorylation, disulfide bond formation and zymogen cleavage all alter the protein after it is made.`,
  },
  [r`Compare prokaryotic and eukaryotic ribosomes.`]: {
    question: r`A cell lysate contains intact 80S ribosomes that separate into 60S and 40S particles. A drug that binds only 30S subunits is added. The drug should:`,
    options: [r`stop these ribosomes, since 30S is their small subunit`, r`stop these ribosomes, since 30S lies inside the 60S`, r`spare these ribosomes, since they are prokaryotic`, r`spare these ribosomes, since none has a 30S subunit`],
    correctAnswer: 3,
    explanation: r`An 80S ribosome (60S + 40S) is eukaryotic and has no 30S subunit, so a 30S-specific drug has nothing to bind. The 30S subunit belongs to the prokaryotic 70S ribosome (50S + 30S); it is not a piece of the 60S, and 80S ribosomes are not prokaryotic.`,
  },
  [r`What catalyzes peptide bond formation?`]: {
    question: r`A student claims that every enzyme-catalyzed step of protein synthesis is carried out by a protein. Which step is the best counterexample?`,
    options: [r`Peptide bond formation on the large subunit`, r`Amino acid attachment to tRNA by a synthetase`, r`Formyl group addition to the initiator Met-tRNA`, r`Signal peptide removal inside the ER lumen`],
    correctAnswer: 0,
    explanation: r`Peptidyl transferase activity belongs to the rRNA of the large subunit, so the peptide bond is made by a ribozyme. Aminoacyl-tRNA synthetases, transformylase and signal peptidase are all protein enzymes.`,
  },
  [r`How does tRNA ensure fidelity?`]: {
    question: r`A correctly charged Cys-tRNA is chemically converted so that it now carries alanine, while its anticodon is unchanged. When a cysteine codon is in the A site, the ribosome will:`,
    options: [r`insert cysteine, because the codon specifies it`, r`reject the tRNA, because its amino acid is wrong`, r`insert alanine, because only the anticodon is read`, r`stall, because a release factor binds the codon`],
    correctAnswer: 2,
    explanation: r`The ribosome checks only codon-anticodon pairing, so the altered tRNA is accepted and alanine goes in. Matching amino acid to tRNA is the synthetase's job and is already done, so the ribosome can neither restore cysteine nor reject the tRNA, and a sense codon does not recruit a release factor.`,
  },
  [r`A nonsense mutation results in:`]: {
    question: r`UAA, UAG and UGA are the stop codons. Which single-base change in the cysteine codon UGC is a nonsense mutation?`,
    options: [r`UGC (Cys) to UGU (Cys)`, r`UGC (Cys) to UCC (Ser)`, r`UGC (Cys) to UGG (Trp)`, r`UGC (Cys) to UGA (stop)`],
    correctAnswer: 3,
    explanation: r`A nonsense mutation turns a sense codon into a stop codon, and UGA is a stop. UGC to UGU keeps cysteine and is silent, while the changes to serine or tryptophan swap one amino acid for another and are missense.`,
  },
  [r`A silent mutation:`]: {
    question: r`A patient's gene carries a single-base substitution in its coding region, yet the purified protein has exactly the normal sequence and length. The best explanation is that the new codon:`,
    options: [r`specifies the same amino acid as the old codon`, r`specifies a chemically similar amino acid`, r`is a stop codon at the very end of the gene`, r`shifts the frame, which is later restored`],
    correctAnswer: 0,
    explanation: r`Because the code is degenerate, a substitution can produce a synonymous codon and leave the protein unchanged: a silent mutation. A similar amino acid is still a missense change in sequence, a new stop shortens the protein, and a substitution cannot shift the reading frame.`,
  },
  [r`Transcription and translation are coupled in:`]: {
    question: r`An electron micrograph shows ribosomes already translating an mRNA whose other end is still being made by RNA polymerase on the DNA. This cell is most likely:`,
    options: [r`a neuron, which has a very active nucleus`, r`a yeast cell, which splices few transcripts`, r`a bacterium, which lacks a nuclear envelope`, r`a hepatocyte, which has abundant rough ER`],
    correctAnswer: 2,
    explanation: r`Ribosomes can load onto a transcript that is still being made only when no nuclear envelope separates the two processes, as in prokaryotes. Neurons, yeast and hepatocytes are eukaryotic, so their mRNA must be finished and exported before translation.`,
  },
  [r`Which type of RNA carries amino acids to the ribosome during translation?`]: {
    question: r`A drug depletes one class of RNA. Ribosomes still assemble on messages, but they stall with empty A sites because no amino acids are being delivered. Which RNA was depleted?`,
    options: [r`Ribosomal RNA (rRNA)`, r`Transfer RNA (tRNA)`, r`Messenger RNA (mRNA)`, r`Micro RNA (miRNA)`],
    correctAnswer: 1,
    explanation: r`tRNA is the adaptor that brings each amino acid to the A site, so losing it leaves ribosomes waiting on the message. Without rRNA the ribosomes would not assemble, without mRNA there would be nothing to assemble on, and miRNA only regulates messages.`,
  },
  [r`The wobble hypothesis explains why:`]: {
    question: r`A bacterium has only two tRNA species for alanine, yet it translates all four alanine codons (GCU, GCC, GCA, GCG) accurately. The best explanation is that:`,
    options: [r`one anticodon can pair with codons differing at the third base`, r`one anticodon can pair with codons differing at the first base`, r`each tRNA can be charged with either of two amino acids`, r`release factors read the two codons that lack a tRNA`],
    correctAnswer: 0,
    explanation: r`Wobble allows relaxed pairing at the codon's third position, so one tRNA reads more than one synonymous codon. The first codon base pairs strictly, a tRNA accepting two amino acids would destroy accuracy, and release factors read only stop codons.`,
  },
  [r`Epigenetic regulation includes:`]: {
    question: r`Identical twins have the same DNA sequence at a tumor-suppressor gene, but the gene is transcriptionally silent in one twin's cells and stays silent through cell divisions. The most likely cause is:`,
    options: [r`a nonsense mutation early in the coding region`, r`deletion of an enhancer upstream of the gene`, r`a frameshift from one inserted nucleotide`, r`methylation of cytosines in the gene's promoter`],
    correctAnswer: 3,
    explanation: r`Epigenetic marks such as promoter DNA methylation silence a gene without changing its sequence and are copied at division. A nonsense mutation, an enhancer deletion and a frameshift are all sequence changes, which the identical sequences rule out.`,
  },
  [r`Autophagy involves:`]: {
    question: r`During prolonged starvation, a liver cell wraps a worn-out mitochondrion in a double membrane. For the contents to be broken down and recycled, this vesicle must fuse with:`,
    options: [r`the Golgi, where its proteins are sorted`, r`a lysosome, where acid hydrolases digest it`, r`a peroxisome, where catalase oxidizes it`, r`the cell surface, where it is released`],
    correctAnswer: 1,
    explanation: r`Autophagy delivers the cell's own components to lysosomes, whose acid hydrolases degrade them into reusable building blocks. The Golgi sorts new proteins, peroxisomes oxidize fatty acids and detoxify peroxide, and release at the cell surface would discard the material instead of recycling it.`,
  },
  [r`Because the released PPi is hydrolyzed, charging one tRNA costs the cell {{c1::2}} ATP equivalents.`]: {
    question: r`A cell charges 30 tRNA molecules with their amino acids, and pyrophosphatase splits all of the pyrophosphate released. How many high-energy phosphate bonds were spent on charging?`,
    options: [r`15 high-energy bonds`, r`30 high-energy bonds`, r`60 high-energy bonds`, r`90 high-energy bonds`],
    correctAnswer: 2,
    explanation: r`Each charging converts ATP to AMP + PPi and the PPi is then split, so 2 bonds are spent per tRNA and 30 × 2 = 60. Answering 30 counts one bond per ATP molecule, 90 counts three bonds as if ATP were stripped to adenosine, and 15 halves the cost instead of doubling it.`,
  },
  [r`Within the Kozak consensus (gccRccAUGG), which two positions most strongly determine whether a eukaryotic AUG is used as the start?`]: {
    question: r`Two capped mRNAs are identical except around their first AUG: mRNA 1 has A at position -3 and G at +4, while mRNA 2 has U at both positions. Each has a second AUG farther downstream. Compared with mRNA 1, mRNA 2 shows:`,
    options: [r`more initiation at the first AUG, by tighter rRNA pairing`, r`more initiation at the downstream AUG, by leaky scanning`, r`no initiation at either AUG, since the cap goes unbound`, r`more initiation at both AUGs, by internal ribosome entry`],
    correctAnswer: 1,
    explanation: r`Losing the purine at -3 and the G at +4 weakens the Kozak context, so more scanning 40S subunits pass the first AUG and start downstream. Pairing with rRNA describes the bacterial Shine-Dalgarno mechanism, cap binding does not depend on these positions, and nothing here adds an internal entry site.`,
  },
  [r`The prokaryotic initiator methionine is formylated {{c1::after the tRNA is already charged}}, by a transformylase acting on Met-tRNA(fMet).`]: {
    question: r`A bacterial mutant lacks transformylase but has a normal methionyl-tRNA synthetase. Which form of the initiator tRNA builds up in these cells?`,
    options: [r`Initiator tRNA left uncharged, beside free formyl-methionine`, r`Initiator tRNA charged with formyl-methionine, as in wild type`, r`Initiator tRNA charged with methionine that is not formylated`, r`Initiator tRNA charged with formate in place of methionine`],
    correctAnswer: 2,
    explanation: r`The synthetase charges the initiator tRNA with methionine first, and transformylase adds the formyl group only afterwards, so without it Met-tRNA(fMet) accumulates unformylated. Free formyl-methionine is never made and then loaded, the formylated form needs the missing enzyme, and formate is not attached in place of the amino acid.`,
  },
  [r`In prokaryotic initiation, what are the distinct jobs of IF1, IF2, and IF3?`]: {
    question: r`In a bacterial mutant with no functional IF3, which defect in initiation is expected most directly?`,
    options: [r`50S subunits join 30S subunits too early`, r`fMet-tRNA is not escorted to the P site`, r`Initiator tRNA enters the open A site`, r`Peptidyl-tRNA fails to shift A to P`],
    correctAnswer: 0,
    explanation: r`IF3 binds the 30S subunit and keeps the 50S subunit off until the initiation complex is ready, so without it the subunits associate prematurely. Escorting fMet-tRNA to the P site is the job of IF2-GTP, keeping the A site blocked is the job of IF1, and moving peptidyl-tRNA from A to P is elongation, driven by EF-G.`,
  },
  [r`Wobble explains how roughly {{c1::40}} distinct tRNAs suffice to read all 61 sense codons.`]: {
    question: r`A student reasons that a cell must contain 64 different tRNAs, one for each codon. Which correction is best?`,
    options: [r`Exactly 61 are needed, one for each of the sense codons`, r`Exactly 20 are needed, one for each of the amino acids`, r`About 40 suffice, because 24 of the codons are stop signals`, r`About 40 suffice, because wobble covers the 61 sense codons`],
    correctAnswer: 3,
    explanation: r`Only 61 codons specify amino acids, and wobble at the third position lets one tRNA read several of them, so roughly 40 tRNAs are enough. Requiring 61 ignores wobble, 20 is too few because one anticodon cannot cover six codons for a single amino acid, and there are 3 stop codons, not 24.`,
  },
  [r`Kinases add phosphate from ATP onto the hydroxyl side chains of {{c1::serine, threonine, and tyrosine}}.`]: {
    question: r`A peptide has the sequence Gly-Ala-Tyr-Val-Leu-Phe-Lys. A protein kinase that uses ATP could attach a phosphate to which residue?`,
    options: [r`Lysine, on its side-chain amine`, r`Phenylalanine, on its ring`, r`Tyrosine, on its hydroxyl group`, r`Alanine, on its methyl group`],
    correctAnswer: 2,
    explanation: r`Kinases phosphorylate side-chain hydroxyls, and tyrosine is the only residue in this peptide that has one (serine and threonine are absent). Phenylalanine is tyrosine without the hydroxyl, lysine's amine is a target for acetylation or ubiquitin instead, and alanine's methyl group is unreactive.`,
  },
  [r`Irreversible activation by {{c1::proteolytic cleavage}} converts zymogens like trypsinogen and prothrombin into their active enzymes.`]: {
    question: r`Trypsinogen is converted to active trypsin in the small intestine. Can the cell later switch trypsin off simply by reversing the step that activated it?`,
    options: [r`Yes; a phosphatase removes the activating group`, r`Yes; a ligase rejoins the fragment when pH rises`, r`No; the added phosphate cannot be hydrolyzed`, r`No; the cut peptide bond is not re-formed`],
    correctAnswer: 3,
    explanation: r`Zymogens are activated by proteolytic cleavage, and a hydrolyzed peptide bond is not rejoined, so activation is irreversible and control must come from inhibitors or degradation. The phosphatase and phosphate options confuse this with reversible phosphorylation, and no ligase reattaches the removed fragment.`,
  },
  [r`Distinguish N-linked from O-linked glycosylation by residue, cellular location, and consensus sequence.`]: {
    question: r`Which three-residue sequence in a protein passing through the ER is a consensus site for N-linked glycosylation?`,
    options: [r`Ser-Ala-Asn`, r`Asn-Ala-Ser`, r`Asn-Ala-Gly`, r`Gln-Ala-Ser`],
    correctAnswer: 1,
    explanation: r`N-linked sugars are attached to the asparagine of Asn-X-Ser/Thr, which Asn-Ala-Ser matches. Ser-Ala-Asn has the order reversed, Asn-Ala-Gly lacks the serine or threonine two residues after the asparagine, and glutamine cannot replace asparagine even though both carry an amide.`,
  },
  [r`A {{c1::K48-linked polyubiquitin}} chain attached to lysine residues targets a protein for destruction by the 26S proteasome.`]: {
    question: r`A cell line expresses only a mutant ubiquitin in which lysine 48 is replaced by arginine, so chains can no longer be built through that position. The most direct effect is that:`,
    options: [r`short-lived proteins build up, since proteasome targeting fails`, r`short-lived proteins vanish, since proteasome targeting speeds up`, r`secreted proteins build up in the ER, since glycosylation fails`, r`membrane proteins leave the bilayer, since lipid anchoring fails`],
    correctAnswer: 0,
    explanation: r`K48-linked chains are the signal the 26S proteasome recognizes, so without lysine 48 normally unstable proteins escape degradation and accumulate. Faster degradation is the opposite of what losing the tag does, and glycosylation and lipid anchoring are separate modifications that do not use ubiquitin.`,
  },
  [r`Why does acetylation of histone tail lysines increase transcription?`]: {
    question: r`Cells are treated with an inhibitor of histone deacetylases (HDACs). What happens to histone tail lysines, chromatin, and transcription of the affected genes?`,
    options: [r`Lysines stay positive, chromatin loosens, transcription rises`, r`Lysines stay neutral, chromatin condenses, transcription falls`, r`Lysines stay positive, chromatin condenses, transcription falls`, r`Lysines stay neutral, chromatin loosens, transcription rises`],
    correctAnswer: 3,
    explanation: r`Blocking HDACs leaves acetyl groups on the lysines, which keeps them neutral, weakens their hold on the negative DNA backbone, and opens chromatin for transcription. The options with positive lysines describe deacetylated histones, and condensed chromatin with less transcription is what active HDACs produce.`,
  },
  [r`What does the signal recognition particle (SRP) bind, and what immediate effect does binding have on the ribosome?`]: {
    question: r`A cell-free system contains ribosomes, SRP, and the mRNA for a secreted protein, but no ER membranes. What happens to translation of this mRNA?`,
    options: [r`It finishes, and the signal sequence is cleaved`, r`It pauses soon after the signal sequence emerges`, r`It never starts, because the cap is not bound`, r`It finishes, and the protein is glycosylated`],
    correctAnswer: 1,
    explanation: r`SRP binds the emerging hydrophobic signal sequence and arrests elongation until it docks at its receptor on the ER membrane, which is missing here. Initiation is unaffected because SRP acts only after the signal appears, and signal cleavage and glycosylation both happen inside the ER.`,
  },
  [r`Which post-translational modification lets clotting factors II, VII, IX, and X chelate calcium, and which vitamin does it require?`]: {
    question: r`A patient taking warfarin makes factor IX of normal length and in normal amounts, but the protein cannot bind Ca²⁺ and so cannot assemble on membranes. Which modification is missing?`,
    options: [r`Gamma-carboxylation of glutamate side chains`, r`Hydroxylation of proline and lysine side chains`, r`N-linked glycosylation of asparagine residues`, r`Phosphorylation of serine and threonine residues`],
    correctAnswer: 0,
    explanation: r`Warfarin blocks vitamin K recycling, and vitamin K is required to gamma-carboxylate glutamates into the paired carboxylates that chelate Ca²⁺. Proline and lysine hydroxylation is the vitamin C-dependent step in collagen, and glycosylation and phosphorylation do not create the calcium-binding sites of clotting factors.`,
  },
  [r`Covalent lipid attachment — prenylation, myristoylation, palmitoylation — serves to {{c1::anchor proteins to membranes}}.`]: {
    question: r`A soluble cytosolic enzyme is engineered so that a myristoyl group is attached at its N-terminus. Where is the enzyme now most likely to be found?`,
    options: [r`Inside the lumen of the endoplasmic reticulum`, r`In the extracellular fluid, after secretion`, r`At the cytosolic face of a cellular membrane`, r`Inside the nucleus, bound tightly to chromatin`],
    correctAnswer: 2,
    explanation: r`A covalently attached lipid tail inserts into the bilayer and holds an otherwise soluble protein against the cytosolic face of a membrane. Entering the ER lumen or being secreted requires a signal sequence, and nuclear import requires a nuclear localization signal, none of which a lipid supplies.`,
  },
  [r`The amino acid is esterified to the 2'- or 3'-OH of the terminal adenosine of the universal {{c1::CCA-3'}} end of tRNA.`]: {
    question: r`An exonuclease removes the last three nucleotides from the 3' end of every tRNA in a cell extract. Which step of protein synthesis fails first?`,
    options: [r`Pairing of anticodons with mRNA codons`, r`Attachment of amino acids to the tRNAs`, r`Binding of the cap by initiation factors`, r`Joining of the two ribosomal subunits`],
    correctAnswer: 1,
    explanation: r`The amino acid is esterified to the terminal adenosine of the 3' CCA end, so tRNAs trimmed of CCA cannot be charged. The anticodon lies in a loop far from the 3' end and is untouched, and cap binding and subunit joining do not involve that end of the tRNA.`,
  },
  [r`Eukaryotic initiation begins when {{c1::eIF4E}} binds the 5' 7-methylguanosine cap, after which the 43S complex scans 5' to 3' for the first AUG.`]: {
    question: r`A eukaryotic mRNA is synthesized without its 7-methylguanosine cap but with a normal coding region and poly(A) tail. It is translated poorly in a cell extract because:`,
    options: [r`eIF2 cannot bind, so the initiator tRNA is never charged`, r`eEF2 cannot bind, so the ribosome fails to translocate`, r`16S rRNA cannot pair with the message upstream of AUG`, r`eIF4E cannot bind, so the 40S subunit is not recruited`],
    correctAnswer: 3,
    explanation: r`eIF4E recognizes the cap and, through eIF4G, brings the 43S complex onto the message to begin scanning, so an uncapped mRNA is rarely loaded. eIF2 delivers initiator tRNA and does not charge it, eEF2 acts in elongation, and 16S rRNA pairing is the bacterial Shine-Dalgarno mechanism.`,
  },
  [r`In wobble pairing, which anticodon position pairs loosely, and with which codon position?`]: {
    question: r`A tRNA with the anticodon 5'-GAA-3' reads two different codons. Which anticodon base pairs loosely, and which two codons (written 5' to 3') does the tRNA read?`,
    options: [r`The 5' G; codons UUC and UUU`, r`The 3' A; codons UUC and CUC`, r`The 5' G; codons UUC and CUC`, r`The 3' A; codons UUC and UUU`],
    correctAnswer: 0,
    explanation: r`Pairing is antiparallel, so the anticodon's 5' base meets the codon's 3' (third) base, and that is the only flexible position: the two codons share UU and differ at the end. The options naming the 3' A pick the strictly paired end of the anticodon, and codons UUC and CUC differ at the first position, which never wobbles.`,
  },
  [r`A protein bound for the mitochondrial matrix versus one bound for secretion — where is each synthesized?`]: {
    question: r`Which pair of proteins is synthesized on ribosomes bound to the rough ER?`,
    options: [r`A nuclear histone and a plasma-membrane receptor`, r`A lysosomal hydrolase and a peroxisomal catalase`, r`A lysosomal hydrolase and a plasma-membrane receptor`, r`A mitochondrial matrix enzyme and a nuclear histone`],
    correctAnswer: 2,
    explanation: r`Lysosomal, plasma-membrane and secreted proteins enter the secretory pathway co-translationally on RER-bound ribosomes. Histones, peroxisomal catalase and mitochondrial matrix enzymes are finished on free cytosolic ribosomes and imported afterwards, so every other pair includes at least one of those.`,
  },
  [r`During elongation, the incoming aminoacyl-tRNA (delivered by EF-Tu) first enters the ribosome's {{c1::A (aminoacyl)}} site.`]: {
    question: r`A bacterial ribosome is stalled with a 9-residue peptidyl-tRNA because the amino acid for codon 10 has run out. Which site sits empty over codon 10, and which factor would normally fill it?`,
    options: [r`The P site, filled by EF-Tu with a charged tRNA`, r`The E site, filled by EF-G with a charged tRNA`, r`The A site, filled by EF-G with a charged tRNA`, r`The A site, filled by EF-Tu with a charged tRNA`],
    correctAnswer: 3,
    explanation: r`Every incoming aminoacyl-tRNA is delivered by EF-Tu to the A site, so with the peptidyl-tRNA in the P site it is the A site that waits over the next codon. The P site is occupied by the chain, the E site holds only departing uncharged tRNA, and EF-G drives translocation, not delivery.`,
  },
  [r`Peptide bond formation is catalyzed by {{c1::23S rRNA acting as a ribozyme}}, not by a ribosomal protein.`]: {
    question: r`In a bacterium, a point mutation that directly alters the catalytic center for peptide bond formation would lie in the gene for:`,
    options: [r`the 23S rRNA of the 50S subunit`, r`the 16S rRNA of the 30S subunit`, r`a core protein of the 50S subunit`, r`a core protein of the 30S subunit`],
    correctAnswer: 0,
    explanation: r`The peptidyl transferase center is built from 23S rRNA in the large (50S) subunit, so the catalyst is RNA. The 16S rRNA of the small subunit handles decoding and Shine-Dalgarno pairing, and ribosomal proteins of either subunit are structural, not the catalyst.`,
  },
  [r`Which ribosomal site holds the tRNA carrying the growing polypeptide, and which tRNA is the only one to enter that site directly?`]: {
    question: r`A bacterial 70S initiation complex has just assembled on an mRNA and no peptide bond has formed yet. Where is fMet-tRNA, and which site is open at codon 2?`,
    options: [r`In the A site, leaving the P site open at codon 2`, r`In the E site, leaving the P site open at codon 2`, r`In the P site, leaving the A site open at codon 2`, r`In the A site, leaving the E site open at codon 2`],
    correctAnswer: 2,
    explanation: r`The initiator tRNA is the one tRNA loaded straight into the P site, which leaves the A site free over the second codon for the first elongator tRNA. Placing fMet-tRNA in the A site treats it like an ordinary elongator tRNA, and the E site only receives tRNAs that have already given up their amino acid.`,
  },
  [r`After peptide bond formation and translocation, the now-deacylated tRNA is ejected from the {{c1::E (exit)}} site.`]: {
    question: r`A tRNA delivered alanine as residue 7 of a protein. The chain has since been passed to the tRNA for residue 8, and the ribosome has translocated once. The alanine tRNA is now:`,
    options: [r`carrying the peptide and about to move to P`, r`uncharged and about to leave the ribosome`, r`carrying one amino acid and awaiting a bond`, r`uncharged and about to enter the A site`],
    correctAnswer: 1,
    explanation: r`After handing its chain to the A-site tRNA, the alanine tRNA is deacylated, and translocation moves it from P to E, from which it is released for recharging. It no longer carries a peptide or an amino acid, and tRNAs never move backward from the exit side into the A site.`,
  },
  [r`In peptide bond formation, which direction is the transfer: P-site peptide onto the A-site amino acid, or the reverse?`]: {
    question: r`A ribosome holds a tRNA carrying Met-Gly-Ser (written N to C) in the P site and Leu-tRNA in the A site. Immediately after the peptidyl transferase reaction, what is found?`,
    options: [r`Met-Gly-Ser-Leu on the P-site tRNA; A-site tRNA empty`, r`Leu-Met-Gly-Ser on the A-site tRNA; P-site tRNA empty`, r`Met-Gly-Ser-Leu on the A-site tRNA; P-site tRNA empty`, r`Leu-Met-Gly-Ser on the P-site tRNA; A-site tRNA empty`],
    correctAnswer: 2,
    explanation: r`The whole peptidyl group moves from the P-site tRNA onto the amino group of the A-site leucine, so leucine becomes the new C-terminal residue on the A-site tRNA. Leaving the chain on the P-site tRNA reverses the direction of transfer, and writing leucine first would mean the chain grows at its N-terminus.`,
  },
  [r`Count the high-energy phosphate bonds spent per amino acid added during elongation.`]: {
    question: r`A cell-free translation system is supplied with tRNAs that are already charged. How many high-energy phosphate bonds must the system itself still spend for each amino acid it adds during elongation?`,
    options: [r`2, both from GTP (tRNA delivery and translocation)`, r`4, two from ATP and two from GTP (the full cost)`, r`1, from GTP (used to form the peptide bond itself)`, r`3, one from ATP and two from GTP (bond and movement)`],
    correctAnswer: 0,
    explanation: r`Of the 4 bonds per residue, 2 are the ATP equivalents spent on charging, which is already done here; the remaining 2 are GTPs used by EF-Tu for delivery and EF-G for translocation. Answering 4 recounts the charging cost, and the peptide bond itself needs no GTP or ATP because it is paid for by the aminoacyl ester bond.`,
  },
  [r`How does EF-Tu improve translational fidelity beyond simply escorting aminoacyl-tRNAs to the ribosome?`]: {
    question: r`A mutant EF-Tu hydrolyzes its GTP the instant it reaches the ribosome, with no pause after the codon is sampled. Compared with normal cells, translation should show:`,
    options: [r`slower elongation with fewer wrong amino acids`, r`faster elongation with more wrong amino acids`, r`normal elongation with more mischarged tRNAs`, r`no elongation, as tRNAs cannot leave the E site`],
    correctAnswer: 1,
    explanation: r`The delay before GTP hydrolysis is a proofreading window in which mismatched tRNAs fall off; removing it speeds delivery but lets more wrong tRNAs stay, so errors rise. Fewer errors is the reverse of the trade-off, mischarging is a synthetase fault that EF-Tu does not cause, and EF-Tu has no role at the E site.`,
  },
  [r`What does eIF2 deliver to the ribosome, and how does phosphorylation of eIF2-alpha regulate it during cellular stress?`]: {
    question: r`Cells express an eIF2-alpha in which the serine targeted by stress kinases is replaced by alanine. When these cells are stressed, how does protein synthesis compare with that in stressed normal cells?`,
    options: [r`Initiation stops, since eIF2B is now permanently sequestered`, r`Initiation stops, since Met-tRNAi can no longer bind to eIF2`, r`Initiation continues, since eIF4E no longer needs the 5' cap`, r`Initiation continues, since eIF2B stays free to reload GTP`],
    correctAnswer: 3,
    explanation: r`Stress shuts down initiation only by phosphorylating eIF2-alpha, which traps the exchange factor eIF2B; an alanine cannot be phosphorylated, so eIF2B keeps regenerating eIF2-GTP and initiation carries on. Sequestration requires the phosphate, the substitution does not touch tRNA binding, and eIF4E's cap binding is a separate control point.`,
  },
  [r`The modified base {{c1::inosine}} at the anticodon wobble position can pair with U, C, or A.`]: {
    question: r`A tRNA has the anticodon 5'-IGC-3', where I is inosine. Which codons (written 5' to 3') can this single tRNA read?`,
    options: [r`Two codons: GCU and GCC`, r`Three codons: GCU, GCC and GCA`, r`Three codons: GCC, GCA and GCG`, r`Two codons: UCG and CCG`],
    correctAnswer: 1,
    explanation: r`The anticodon's 5' inosine pairs with the codon's third base and accepts U, C or A, while GC of the anticodon fixes the first two codon bases as G and C. Stopping at GCU and GCC gives the range of a wobble G, inosine does not pair with G so GCG is excluded, and UCG and CCG put the variation at the first codon position.`,
  },
  [r`State the wobble pairing options for G and for U when each sits at the 5' position of the anticodon.`]: {
    question: r`A tRNA has the unmodified anticodon 5'-UUU-3'. Which two codons, written 5' to 3', can it read?`,
    options: [r`AAA and AAU`, r`AAA and GAA`, r`AAA and AAG`, r`AAA and AAC`],
    correctAnswer: 2,
    explanation: r`A U at the anticodon's 5' (wobble) position pairs with A or G in the codon's third position, giving AAA and AAG. A third-position U or C would need a wobble G or inosine, and GAA changes the first codon base, which must pair strictly.`,
  },
  [r`Outline the two chemical steps by which an aminoacyl-tRNA synthetase charges its tRNA.`]: {
    question: r`A purified aminoacyl-tRNA synthetase is mixed with its amino acid and ATP, but no tRNA is added. Which species forms and stays bound to the enzyme?`,
    options: [r`Aminoacyl-tRNA, with AMP released`, r`Aminoacyl-ADP, with Pi released`, r`Aminoacyl-PPi, with AMP released`, r`Aminoacyl-AMP, with PPi released`],
    correctAnswer: 3,
    explanation: r`Step 1 joins the amino acid to the alpha phosphate of ATP, making the aminoacyl-AMP (adenylate) and releasing PPi; step 2 cannot follow without tRNA. ATP is split between its alpha and beta phosphates, so neither an ADP nor a pyrophosphate intermediate forms, and aminoacyl-tRNA cannot appear when no tRNA is present.`,
  },
  [r`Ribosomal translocation advances the mRNA exactly {{c1::3 nucleotides (one codon)}} and requires EF-G (prokaryotes) or eEF2 (eukaryotes) plus GTP.`]: {
    question: r`The A site of a ribosome sits over nucleotides 31 to 33 of an mRNA, numbered from the 5' end. After two rounds of translocation by EF-G, the A site sits over:`,
    options: [r`nucleotides 37 to 39`, r`nucleotides 34 to 36`, r`nucleotides 33 to 35`, r`nucleotides 25 to 27`],
    correctAnswer: 0,
    explanation: r`Each translocation moves the ribosome exactly one codon, 3 nucleotides, toward the 3' end, so two rounds shift the A site by 6 to nucleotides 37 to 39. Positions 34 to 36 count only one round, 33 to 35 moves one nucleotide per round, and 25 to 27 moves toward the 5' end.`,
  },
  [r`The Shine-Dalgarno sequence, a purine-rich element about 8 nt upstream of AUG, base-pairs with the 3' end of the {{c1::16S rRNA}}.`]: {
    question: r`In a bacterial mRNA, the purine-rich stretch about 8 nucleotides upstream of the start codon is mutated to pyrimidines, and the protein is no longer made. Which interaction was lost directly?`,
    options: [r`Base pairing with the 3' end of 23S rRNA`, r`Base pairing with the 3' end of 16S rRNA`, r`Base pairing with the fMet-tRNA anticodon`, r`Binding of the cap-recognition factor eIF4E`],
    correctAnswer: 1,
    explanation: r`That purine-rich element is the Shine-Dalgarno sequence, which pairs with the 3' end of the 16S rRNA in the 30S subunit to place AUG in the P site. The 23S rRNA belongs to the 50S subunit and catalyzes bond formation, the initiator anticodon pairs with AUG itself, and eIF4E is a eukaryotic cap-binding factor.`,
  },
  [r`Stop codons are read by protein release factors, and the finished chain is cleaved from its tRNA by {{c1::a water molecule}} in the peptidyl transferase center.`]: {
    question: r`At termination, the peptidyl transferase center passes the finished chain to a final acceptor instead of to another aminoacyl-tRNA. What is that acceptor, and what does the released chain end in?`,
    options: [r`A last amino acid, giving one extra C-terminal residue`, r`The release factor, giving a chain bound to that protein`, r`A water molecule, giving a free C-terminal carboxyl group`, r`A GTP molecule, giving a phosphorylated C-terminal end`],
    correctAnswer: 2,
    explanation: r`The release factor positions water in the peptidyl transferase center, and water hydrolyzes the ester bond to the tRNA, leaving an ordinary free carboxyl at the C-terminus. No tRNA reads a stop codon, so no extra residue is added, the release factor does not stay attached to the chain, and GTP is not the acceptor of the peptide.`,
  },
  [r`How do synthetases avoid mischarging chemically similar amino acids such as valine onto tRNA-Ile?`]: {
    question: r`Isoleucyl-tRNA synthetase occasionally activates valine, which is smaller than isoleucine by one methylene group. Where is this mistake normally corrected?`,
    options: [r`At the ribosomal A site, which rejects the wrong residue`, r`At the synthetase activation site, which excludes valine`, r`At the ribosomal P site, which cleaves the wrong residue`, r`At the synthetase editing site, which hydrolyzes it off`],
    correctAnswer: 3,
    explanation: r`A second, hydrolytic editing site on the synthetase admits amino acids smaller than the correct one and removes them: the second sieve. The activation site can exclude only larger amino acids, so valine gets in, and the ribosome inspects the codon-anticodon match and never the amino acid.`,
  },
  [r`After SRP docks at its ER receptor (GTP-dependent), translation resumes and the chain threads through the {{c1::Sec61 translocon}} into the ER lumen.`]: {
    question: r`A cell has normal SRP and SRP receptor but a nonfunctional Sec61 complex. What happens to a nascent secretory protein in this cell?`,
    options: [r`It never reaches the ER and is finished on a free ribosome`, r`It reaches the ER membrane but cannot cross into the lumen`, r`It crosses into the lumen but keeps its signal sequence`, r`It crosses into the lumen but cannot be folded there`],
    correctAnswer: 1,
    explanation: r`SRP and its receptor still bring the ribosome to the ER membrane, but Sec61 is the channel the chain threads through, so entry into the lumen is blocked. Failing to reach the ER would be an SRP or receptor defect, and the two options with the chain inside the lumen assume a working channel.`,
  },
  [r`Aminoglycosides cause mRNA misreading and tetracyclines block A-site tRNA entry; both target the bacterial {{c1::30S}} subunit.`]: {
    question: r`With drug X, bacteria make full-length proteins that contain many wrong amino acids. With drug Y, their ribosomes sit with empty A sites. Which assignment fits?`,
    options: [r`X is a tetracycline, Y is an aminoglycoside; both bind 30S`, r`X is an aminoglycoside, Y is a tetracycline; both bind 50S`, r`X is an aminoglycoside, Y is a tetracycline; both bind 30S`, r`X is a tetracycline, Y is an aminoglycoside; both bind 50S`],
    correctAnswer: 2,
    explanation: r`Misreading of codons is the aminoglycoside effect and blocked entry of aminoacyl-tRNA into the A site is the tetracycline effect, and both drugs act on the 30S subunit, where decoding occurs. The swapped options exchange the two mechanisms, and the 50S subunit is the target of macrolides and chloramphenicol instead.`,
  },
  [r`On the 50S subunit, which antibiotic class blocks the exit tunnel and which drug inhibits peptidyl transferase — and why can they cause human toxicity?`]: {
    question: r`Bacterial ribosomes treated with erythromycin, a macrolide, form the first few peptide bonds and then stall holding a short peptide. Why?`,
    options: [r`The peptidyl transferase center can no longer form bonds`, r`The nascent chain cannot pass through the blocked exit tunnel`, r`The A site of the 30S subunit can no longer accept tRNA`, r`The 30S subunit misreads codons and meets a false stop`],
    correctAnswer: 1,
    explanation: r`Macrolides plug the polypeptide exit tunnel of the 50S subunit, so synthesis halts once the short chain reaches the blockage. Loss of bond formation is the chloramphenicol mechanism and would prevent even the first bonds, while A-site blockade and misreading are 30S effects of tetracyclines and aminoglycosides.`,
  },
  [r`How does HIV produce Gag and Gag-Pol from one mRNA in a fixed ratio?`]: {
    question: r`A mutation in an HIV genome makes every ribosome slip back one nucleotide at the slippery sequence, instead of only a small fraction of them. What do infected cells now produce?`,
    options: [r`Nearly all free Gag, with too little of the Gag-Pol fusion`, r`Separate Gag and Pol proteins in an equal one-to-one ratio`, r`Neither protein, as ribosomes halt at the slippery sequence`, r`Nearly all Gag-Pol fusion, with too little of the free Gag`],
    correctAnswer: 3,
    explanation: r`Ribosomes that frameshift read past the gag stop codon into pol and make the Gag-Pol fusion, so if all of them shift, almost no Gag alone is made and the required ratio is lost. Mostly free Gag is what happens with no frameshifting, Pol is never made as a separate protein from its own start, and slipping changes the frame without stopping the ribosome.`,
  },
  [r`Poliovirus shuts off host protein synthesis by cleaving {{c1::eIF4G}}, yet its own RNA is still translated because it carries an {{c2::IRES}}.`]: {
    question: r`Cells contain two capped reporter mRNAs. Reporter A has an ordinary 5' leader, and reporter B has an internal ribosome entry site in its leader. After poliovirus infection cleaves eIF4G, what happens to reporter output?`,
    options: [r`A falls sharply while B continues to be made`, r`B falls sharply while A continues to be made`, r`A and B both fall, since both carry a cap`, r`A and B both rise, since host mRNAs are gone`],
    correctAnswer: 0,
    explanation: r`Cleaving eIF4G breaks the link between the cap-binding factor and the 40S subunit, so cap-dependent reporter A is shut off, while the IRES in B recruits the small subunit directly. Having a cap does not make B depend on it, and A cannot rise when the pathway it relies on has been cut.`,
  },
  [r`After stress, a sucrose gradient shows ribosomes shifted out of heavy polysome fractions into the monosome peak. What step was inhibited?`]: {
    question: r`Drug A blocks translation initiation, and drug B freezes elongating ribosomes in place on the mRNA. Thirty minutes after each drug is added, what do sucrose gradient profiles show?`,
    options: [r`A: polysomes persist; B: polysomes collapse to monosomes`, r`A: polysomes collapse to monosomes; B: polysomes persist`, r`A and B: polysomes collapse to monosomes in both cases`, r`A and B: polysomes persist in the heavy fractions in both`],
    correctAnswer: 1,
    explanation: r`With initiation blocked, ribosomes already on messages finish and run off while none reload, so polysomes empty into the monosome peak; frozen elongating ribosomes stay on the mRNA and polysomes are preserved. The reversed option swaps the two signatures, and the two "both" options ignore that the drugs act at different steps.`,
  },
  [r`Cap-dependent initiation is controlled by mTOR, which phosphorylates {{c1::4E-BP1}} to release {{c2::eIF4E}} and switch on growth-related translation.`]: {
    question: r`Cells are treated with rapamycin, which inhibits mTOR. What is the state of 4E-BP1, and what happens to cap-dependent initiation?`,
    options: [r`4E-BP1 is unphosphorylated and holds eIF4E, so initiation falls`, r`4E-BP1 is phosphorylated and holds eIF4E, so initiation falls`, r`4E-BP1 is unphosphorylated and frees eIF4E, so initiation rises`, r`4E-BP1 is phosphorylated and frees eIF4E, so initiation rises`],
    correctAnswer: 0,
    explanation: r`Without mTOR activity 4E-BP1 stays unphosphorylated, and in that state it binds eIF4E and keeps it from assembling the cap-binding complex, so initiation drops. Phosphorylated 4E-BP1 that frees eIF4E is the picture with active mTOR, and the two mixed options pair the phosphorylation state with the wrong binding behavior.`,
  },
  [r`Why is the common CFTR mutation delta F508 a folding problem rather than a channel problem?`]: {
    question: r`Two drug types exist for cystic fibrosis: correctors, which help CFTR fold, and potentiators, which hold open channels already at the cell surface. For a patient homozygous for delta F508, which is needed first, and why?`,
    options: [r`A potentiator, because the protein sits at the surface but stays shut`, r`A corrector, because the mutant mRNA is never translated at all`, r`A corrector, because the protein is degraded before reaching the surface`, r`A potentiator, because the protein is cut short by a stop codon`],
    correctAnswer: 2,
    explanation: r`Delta F508 CFTR misfolds, is caught by ER quality control and is degraded, so a drug that assists folding is needed before any channel can reach the membrane. A potentiator alone has almost no surface protein to act on, the mutant mRNA is translated normally, and a single-residue deletion does not create a stop codon.`,
  },
  [r`One mRNA is usually read by many ribosomes at once, spaced roughly every {{c1::80}} nucleotides, forming a {{c2::polysome}}.`]: {
    question: r`The coding region of an mRNA is 2,400 nucleotides long. If it is fully loaded with ribosomes at the typical spacing, about how many ribosomes does this polysome carry?`,
    options: [r`About 3 ribosomes`, r`About 300 ribosomes`, r`About 800 ribosomes`, r`About 30 ribosomes`],
    correctAnswer: 3,
    explanation: r`Ribosomes on a polysome sit roughly 80 nucleotides apart, so 2,400 ÷ 80 = 30 ribosomes. About 3 and about 300 are tenfold slips in that division, and 800 comes from dividing by 3 as though each codon held its own ribosome.`,
  },
  [r`Why might a human protein expressed in E. coli be inactive even though its amino acid sequence is correct?`]: {
    question: r`A human hormone that needs sugar chains on asparagine residues is produced from its cDNA in E. coli. The amino acid sequence is correct, but the product is inactive. What is the most likely reason?`,
    options: [r`Bacteria cannot splice the introns from its mRNA`, r`Bacteria cannot read several human sense codons`, r`Bacteria cannot join its amino acids correctly`, r`Bacteria cannot attach its N-linked sugar chains`],
    correctAnswer: 3,
    explanation: r`E. coli lacks the ER and Golgi machinery for eukaryotic glycosylation, so the hormone is made with the right sequence but without the sugars it needs. A cDNA has no introns to splice, the genetic code is shared so the codons are read, and a correct sequence shows the peptide bonds were made properly.`,
  },
  [r`Cycloheximide stops cytosolic protein synthesis while a few mitochondrial proteins are still made; chloramphenicol does the reverse. Explain.`]: {
    question: r`Human cells are given a radioactive amino acid in the presence of cycloheximide. Which proteins become labeled?`,
    options: [r`Most enzymes imported into the mitochondrial matrix`, r`A few subunits encoded by the mitochondrial genome`, r`Secreted proteins made on the rough ER membrane`, r`Histones made in the cytosol for nuclear import`],
    correctAnswer: 1,
    explanation: r`Cycloheximide blocks 80S cytosolic ribosomes, so only the handful of proteins made on the 70S-like ribosomes inside mitochondria are still synthesized and labeled. Imported matrix enzymes, secreted proteins and histones are all made on 80S ribosomes, free or ER-bound, and are shut off.`,
  },
  [r`Iron controls ferritin and transferrin receptor expression through the same iron-response elements. How can one signal give opposite outcomes?`]: {
    question: r`A cell line carries a deletion of the iron-response element in the 5' UTR of its ferritin mRNA; its transferrin receptor mRNA is normal. When these cells are starved of iron, ferritin:`,
    options: [r`is made at a high rate despite the low iron`, r`is made at a low rate, as in normal cells`, r`mRNA is quickly degraded by nucleases`, r`is made only once receptor mRNA decays`],
    correctAnswer: 0,
    explanation: r`In low iron, IRP normally binds the 5' IRE of ferritin mRNA and blocks initiation; with no IRE there is nothing to bind, so ferritin is translated freely. A low rate is the normal, IRE-dependent response, and control of mRNA stability by IRP applies to the 3' UTR elements of the receptor message, not to ferritin.`,
  },
  [r`Polyglutamine diseases such as Huntington arise when a CAG expansion makes a protein prone to {{c1::misfolding and aggregation}}, a toxic gain of function.`]: {
    question: r`A CAG repeat expansion causes a neurodegenerative disease through the mechanism typical of polyglutamine disorders. Which treatment strategy best matches that mechanism?`,
    options: [r`Adding a normal gene copy, since the product is missing`, r`Blocking the normal allele, since its product aggregates`, r`Silencing the mutant allele, since its product is toxic`, r`Adding a release factor, since the repeat stops ribosomes`],
    correctAnswer: 2,
    explanation: r`The expanded polyglutamine protein misfolds and aggregates, a toxic gain of function, so the harm is removed by lowering the mutant product. Adding a normal copy treats a loss of function and leaves the toxic protein in place, the normal allele's product is not the one that aggregates, and CAG encodes glutamine, not a stop signal.`,
  },
  [r`Translation misincorporates about one amino acid in $10^{4}$, far worse than DNA replication. Why is that tolerable?`]: {
    question: r`A 500-residue protein is made with an error rate of one wrong amino acid per $10^{4}$ residues. About what fraction of the copies contain an error, and why can the cell accept this?`,
    options: [r`About 5%; faulty copies are degraded and replaced`, r`About 0.5%; faulty copies are fixed by mismatch repair`, r`About 50%; faulty copies are passed to daughter cells`, r`About 5%; faulty copies are corrected by the ribosome`],
    correctAnswer: 0,
    explanation: r`500 residues × 1 error per 10,000 gives about 0.05 errors per copy, so roughly 5% of copies are flawed; they are simply turned over while many good copies do the job. Mismatch repair acts on DNA, protein errors are not inherited the way replication errors are, and the ribosome cannot go back and fix a residue already added.`,
  },
  [r`{{c1::Puromycin}} resembles an aminoacyl-tRNA, enters the A site, and causes premature release of the peptide attached to it.`]: {
    question: r`Bacterial and human cells are each treated with puromycin. What translation products are found in both kinds of cell?`,
    options: [r`Full-length proteins carrying many wrong residues`, r`Full-length proteins still bound to their tRNAs`, r`No peptides, since no initiation complex can form`, r`Short peptides of many lengths ending in the drug`],
    correctAnswer: 3,
    explanation: r`Puromycin mimics an aminoacyl-tRNA, accepts the growing chain in the A site, and the chain then falls off, so truncated peptides capped with the drug accumulate in any cell. Wrong residues in full-length proteins are the aminoglycoside pattern, chains stuck on tRNA would mean failed release, and puromycin does not block initiation.`,
  },
  [r`Ricin and Shiga toxin are N-glycosidases that depurinate the large-subunit {{c1::rRNA}}, permanently blocking elongation factor binding.`]: {
    question: r`After ricin exposure, a cell's mRNA, tRNAs and ribosomal proteins are all intact, yet translation has stopped. Why can a single ricin molecule kill the cell?`,
    options: [r`It is a ligand that binds one mRNA and stalls every ribosome reading it`, r`It is a protease that cleaves the elongation factors of many ribosomes`, r`It is an enzyme that removes one purine from the rRNA of many ribosomes`, r`It is an enzyme that adds ADP-ribose to the eEF2 of many ribosomes`],
    correctAnswer: 2,
    explanation: r`Ricin is an N-glycosidase that clips a single purine base from large-subunit rRNA, and because it is a catalyst it disables ribosome after ribosome so elongation factors can no longer bind. It does not bind mRNA or cut proteins, and ADP-ribosylation of eEF2 is the mechanism of diphtheria toxin.`,
  },
  [r`Alpha-1 antitrypsin deficiency damages both liver and lung. How does one misfolded protein produce two different mechanisms?`]: {
    question: r`A patient is homozygous for a rare "null" allele that produces no alpha-1 antitrypsin protein at all, unlike the common allele that makes a misfolded, polymerizing protein. Which disease pattern is expected?`,
    options: [r`Liver disease without emphysema, since elastase stays inhibited`, r`Emphysema without liver disease, since nothing builds up in the ER`, r`Both emphysema and liver disease, as with the misfolded variant`, r`Neither disease, since an absent protein cannot be harmful`],
    correctAnswer: 1,
    explanation: r`The lung damage is a loss of function: with no inhibitor, neutrophil elastase destroys alveolar walls, so emphysema still occurs. The liver damage is a toxic gain of function from polymers retained in hepatocyte ER, and with no protein made there is nothing to accumulate, so the liver is spared.`,
  },
  [r`Heat or a load of misfolded protein activates the transcription factor {{c1::HSF1}}, which induces chaperone genes such as Hsp70.`]: {
    question: r`Cells kept at normal temperature are given a proteasome inhibitor, and misfolded proteins build up. Within hours, Hsp70 mRNA rises sharply. What best explains the rise?`,
    options: [r`Misfolded proteins activate IRP, which stabilizes chaperone mRNA`, r`Misfolded proteins activate mTOR, which induces chaperone genes`, r`Misfolded proteins activate HSF1, which induces chaperone genes`, r`Misfolded proteins activate SRP, which exports chaperone mRNA`],
    correctAnswer: 2,
    explanation: r`A load of misfolded protein, not heat itself, is the trigger: it activates the transcription factor HSF1, which switches on chaperone genes such as Hsp70. IRP responds to iron, mTOR responds to nutrients and controls cap-dependent translation, and SRP targets ribosomes to the ER and does not export mRNA.`,
  },
  [r`A {{c1::K63}}-linked polyubiquitin chain serves as a signaling and trafficking tag, unlike the {{c2::K48}} chain that sends a protein to the proteasome.`]: {
    question: r`Protein X carries a polyubiquitin chain linked through lysine 48, and protein Y carries one linked through lysine 63. Adding a proteasome inhibitor to the cells should most directly:`,
    options: [r`stabilize X, with little effect on the signaling role of Y`, r`stabilize Y, with little effect on the signaling role of X`, r`stabilize both, since any ubiquitin chain means degradation`, r`stabilize neither, since lysosomes degrade both proteins`],
    correctAnswer: 0,
    explanation: r`K48-linked chains send a protein to the proteasome, so blocking the proteasome spares X, while K63-linked chains mark Y for signaling or trafficking and not for proteasomal destruction. The reversed option swaps the two linkages, and treating every chain as a degradation tag ignores that linkage sets the meaning.`,
  },
  [r`Translation runs at about {{c1::15-20}} amino acids per second in bacteria but only about {{c2::2-6}} per second in eukaryotes.`]: {
    question: r`A bacterium translating at about 20 amino acids per second and a eukaryotic cell translating at about 5 per second each make a 600-residue protein. About how long does each ribosome take?`,
    options: [r`About 2 min in the bacterium and 30 s in the eukaryote`, r`About 30 s in the bacterium and 2 min in the eukaryote`, r`About 3 s in the bacterium and 12 s in the eukaryote`, r`About 30 min in the bacterium and 2 h in the eukaryote`],
    correctAnswer: 1,
    explanation: r`600 ÷ 20 = 30 s for the bacterial ribosome and 600 ÷ 5 = 120 s, or 2 min, for the eukaryotic one. The reversed option makes eukaryotes the faster translators, 3 s and 12 s drop a factor of ten, and 30 min and 2 h read the per-second rates as per-minute rates.`,
  },
  [r`Why does measuring C-peptide distinguish an insulinoma from surreptitious insulin injection?`]: {
    question: r`A patient with repeated episodes of low blood glucose has a very high plasma insulin level but an undetectable C-peptide level. Which cause fits these results?`,
    options: [r`An insulinoma, which secretes insulin without C-peptide`, r`An insulinoma, which secretes only uncleaved proinsulin`, r`Injected insulin, which speeds the clearance of C-peptide`, r`Injected insulin, which is made with no C-peptide in it`],
    correctAnswer: 3,
    explanation: r`Insulin made by the body is cut from proinsulin and released with an equal amount of C-peptide, so high insulin with no C-peptide points to manufactured insulin, which also suppresses the patient's own secretion. An insulinoma releases C-peptide along with its insulin, and injected insulin lowers C-peptide by shutting off beta cells, not by clearing it.`,
  },
}
